<template>
  <BioNexusDialog ref="dialog" size="wide" dialog-class="routine-entry-dialog" shell-class="routine-entry-shell" body-class="routine-entry-body" :prevent-close="saving || dirty" @before-close="requestClose" :kicker="mode === 'create' ? 'Nuevo registro' : 'Editar registro'" :title="mode === 'create' ? 'Crear rutina' : 'Editar rutina'" @close="handleClosed">
    <section class="routine-body">
      <BioNexusSectionPanel class="routine-section" title="Información de la rutina" icon="assignment" description="Define la descripción y los detalles que identifican la rutina." variant="accent">
        <div class="routine-fields">
          <BioNexusFormField label="Descripción" field-id="routine-description" :error="descriptionError" required><input id="routine-description" ref="firstInput" v-model="draft.description" class="bio-nexus-field" @input="syncDirty" maxlength="50"></BioNexusFormField>
          <BioNexusFormField label="Detalles" field-id="routine-details" :help="draft.details.length + ' de 200 caracteres'"><textarea id="routine-details" v-model="draft.details" class="bio-nexus-field" maxlength="200" @input="syncDirty" rows="2"></textarea></BioNexusFormField>
        </div>
      </BioNexusSectionPanel>
      <BioNexusSectionPanel class="routine-section" title="Gestión de exámenes" icon="playlist_add_check" description="Agrega los exámenes de la rutina y organiza el orden en que deben mostrarse." variant="accent">
        <div class="routine-picker">
          <section class="routine-panel">
            <BioNexusFormField label="Buscar examen" field-id="routine-search"><input id="routine-search" v-model="search" class="bio-nexus-field" type="search" autocomplete="off"></BioNexusFormField>
            <div class="routine-list available-list">
              <article v-for="exam in available" :key="exam.id" class="routine-row available-row"><span class="catalog-mark" aria-hidden="true">+</span><span class="routine-row-copy"><strong>{{ exam.description }}</strong><small>{{ exam.abbreviation }}</small></span><div class="available-actions"><BioNexusActionButton size="sm" variant="secondary" icon="visibility" icon-only shape="circle" label="Detalle" @click="openDetail(exam)" /><BioNexusActionButton size="sm" variant="primary" icon="add" icon-only shape="circle" label="Agregar" @click="add(exam)" /></div></article>
              <p v-if="!available.length" class="routine-empty">No hay exámenes disponibles.</p>
            </div>
          </section>
          <section class="routine-panel selected-panel">
            <header><strong>Exámenes seleccionados</strong><span>{{ draft.exams.length }}</span></header>
            <p v-if="attempted && !draft.exams.length" class="routine-error">Selecciona al menos un examen.</p>
            <div class="routine-list selected-list" @dragover.prevent="autoScroll">
              <div v-for="(exam,index) in draft.exams" :key="exam.examId" :data-routine-key="exam.examId" class="routine-row selected-row" :class="{ dragging: dragId === exam.examId, 'keyboard-selected': keyboardId === exam.examId }" draggable="true" tabindex="0" @focus="selectKeyboard(exam.examId)" @click="activateKeyboardSelection(exam.examId,$event)" @dragstart="startDrag(exam.examId,$event)" @dragenter.prevent="previewDrag(index,$event)" @dragover.prevent="previewDrag(index,$event)" @drop.prevent="endDrag" @dragend="endDrag">
                <span class="order-number">{{ index + 1 }}</span><span class="drag-icon" aria-hidden="true">⋮⋮</span><span class="routine-row-copy"><strong>{{ exam.description }}</strong><small>{{ exam.abbreviation || "Examen de catálogo" }}</small></span>
                <div class="routine-moves"><BioNexusActionButton icon="arrow_upward" icon-only shape="circle" size="sm" variant="secondary" label="Subir" :disabled="index===0" @click.stop="move(index,-1)" /><BioNexusActionButton icon="arrow_downward" icon-only shape="circle" size="sm" variant="secondary" label="Bajar" :disabled="index===draft.exams.length-1" @click.stop="move(index,1)" /><BioNexusActionButton size="sm" variant="danger" icon="delete" icon-only shape="circle" label="Quitar" @click.stop="remove(index)" /></div>
              </div>
            </div>
          </section>
        </div>
      </BioNexusSectionPanel>
      <div v-if="errorMessage" class="bio-nexus-message bio-nexus-message-error">{{ errorMessage }}</div>
    </section>
    <template #footer><BioNexusActionButton variant="secondary" icon="cancel" :disabled="saving" @click="requestClose">Cancelar</BioNexusActionButton><BioNexusActionButton variant="primary" :icon="mode === 'create' ? 'create' : 'save'" :loading="saving" :disabled="submitDisabled" @click="submit">{{ mode === 'create' ? 'Crear' : 'Guardar' }}</BioNexusActionButton></template>
  </BioNexusDialog>
  <ExamDetailDialog ref="detailDialog" /><BioNexusConfirmDialog ref="discardDialog" />
</template>
<script setup>
import { computed, nextTick, onBeforeUnmount, reactive, ref } from "vue";
import BioNexusDialog from "@/components/ui/BioNexusDialog.vue";
import ExamDetailDialog from "@/components/exams/ExamDetailDialog.vue";
import BioNexusFormField from "@/components/ui/BioNexusFormField.vue";
import BioNexusActionButton from "@/components/ui/BioNexusActionButton.vue";
import BioNexusConfirmDialog from "@/components/ui/BioNexusConfirmDialog.vue";
import BioNexusSectionPanel from "@/components/ui/BioNexusSectionPanel.vue";
const props=defineProps({saving:Boolean,canCreate:Boolean,canUpdate:Boolean,exams:{type:Array,default:()=>[]}});const emit=defineEmits(["submit"]);const dialog=ref(null),detailDialog=ref(null),discardDialog=ref(null),firstInput=ref(null),mode=ref("create"),current=ref(null),search=ref(""),attempted=ref(false),errorMessage=ref(""),original=ref(""),dirty=ref(false),initializing=ref(false),dragId=ref(null),keyboardId=ref(null),keyboardOriginal=ref([]);const draft=reactive({description:"",details:"",exams:[]});
const values=computed(()=>({description:draft.description.trim(),details:draft.details.trim(),registered_exams:draft.exams.map(item=>{const row={examId:item.examId};if(Object.prototype.hasOwnProperty.call(item,"active"))row.active=Boolean(item.active);return row})}));const signature=computed(()=>JSON.stringify(values.value));const descriptionError=computed(()=>attempted.value&&!values.value.description?"La descripción es obligatoria.":"");const isValid=computed(()=>Boolean(values.value.description)&&draft.exams.length>0);const submitDisabled=computed(()=>initializing.value||props.saving||(mode.value==="create"?(!props.canCreate||!isValid.value):(!props.canUpdate||!isValid.value||!dirty.value)));const available=computed(()=>{const query=search.value.trim().toLowerCase(),used=new Set(draft.exams.map(item=>item.examId));return props.exams.filter(exam=>!exam.annulled&&!used.has(exam.id)&&(!query||`${exam.description} ${exam.abbreviation}`.toLowerCase().includes(query)))});
function assign(row){draft.description=row?.description||"";draft.details=row?.details||"";draft.exams=(row?.registered_exams||[]).map(item=>({...item,description:item.description||props.exams.find(exam=>exam.id===item.examId)?.description||`Examen ${item.examId}`}))}function snapshot(){return JSON.stringify(values.value)}function syncDirty(){dirty.value=!initializing.value&&snapshot()!==original.value}async function show(){await dialog.value?.open();await nextTick();original.value=snapshot();dirty.value=false;initializing.value=false;firstInput.value?.focus()}async function openCreate(){initializing.value=true;mode.value="create";current.value=null;assign(null);attempted.value=false;errorMessage.value="";search.value="";await show()}async function openEdit(row){initializing.value=true;mode.value="edit";current.value=row;assign(row);attempted.value=false;errorMessage.value="";search.value="";await show()}function openDetail(exam){detailDialog.value?.open(exam)}async function add(exam){draft.exams.push({examId:exam.id,description:exam.description,abbreviation:exam.abbreviation});await nextTick();syncDirty();keyboardId.value=null;selectKeyboard(exam.id);focusRow(exam.id,{block:"end"})}function remove(index){draft.exams.splice(index,1);syncDirty();keyboardId.value=null}function move(index,delta){const target=index+delta;if(target<0||target>=draft.exams.length)return;const[row]=draft.exams.splice(index,1);draft.exams.splice(target,0,row);syncDirty();focusRow(row.examId)}function selectKeyboard(id){if(keyboardId.value!==id){keyboardId.value=id;keyboardOriginal.value=draft.exams.map(item=>item.examId)}}function activateKeyboardSelection(id,event){event?.preventDefault?.();event?.stopPropagation?.();if(keyboardId.value===id)return;keyboardId.value=null;selectKeyboard(id);focusRow(id)}function focusRow(id,options={}){nextTick(()=>{const row=document.querySelector(`[data-routine-key="${id}"]`);row?.focus({preventScroll:true});row?.scrollIntoView({block:options.block||"nearest",inline:"nearest",behavior:options.behavior||"auto"})})}function moveSelected(delta){const index=draft.exams.findIndex(item=>item.examId===keyboardId.value);if(index>=0)move(index,delta)}function cancelKeyboard(){if(!keyboardId.value)return;const byId=new Map(draft.exams.map(item=>[item.examId,item]));draft.exams.splice(0,draft.exams.length,...keyboardOriginal.value.map(id=>byId.get(id)).filter(Boolean));syncDirty();const id=keyboardId.value;keyboardId.value=null;focusRow(id)}function handleKey(event){if(!dialog.value?.element?.open||!keyboardId.value||event.target?.matches?.("input,textarea,select"))return;if(event.key==="ArrowUp"){event.preventDefault();moveSelected(-1)}else if(event.key==="ArrowDown"){event.preventDefault();moveSelected(1)}else if(event.key==="Enter"){event.preventDefault();keyboardId.value=null}else if(event.key==="Escape"){event.preventDefault();cancelKeyboard()}}function startDrag(id,event){dragId.value=id;if(event.dataTransfer){event.dataTransfer.effectAllowed="move";event.dataTransfer.setData("text/plain",String(id))}}function previewDrag(targetIndex,event){const source=draft.exams.findIndex(item=>item.examId===dragId.value);if(source<0)return;const rectangle=event.currentTarget.getBoundingClientRect();let target=targetIndex+(event.clientY>=rectangle.top+rectangle.height/2?1:0);if(source<target)target--;if(target===source)return;const[row]=draft.exams.splice(source,1);draft.exams.splice(target,0,row);syncDirty()}function autoScroll(event){const list=event.currentTarget,rect=list.getBoundingClientRect();if(event.clientY<rect.top+36)list.scrollTop-=8;else if(event.clientY>rect.bottom-36)list.scrollTop+=8}function endDrag(){dragId.value=null}function submit(){attempted.value=true;if(descriptionError.value||!draft.exams.length||submitDisabled.value)return;emit("submit",{mode:mode.value,record:current.value,values:values.value})}async function requestClose(){if(props.saving)return;if(dirty.value){const confirmed=await discardDialog.value?.ask({kicker:"Confirmación",title:"Descartar cambios",message:"Hay cambios sin guardar. ¿Deseas salir y descartarlos?",icon:"warning",variant:"danger",confirmIcon:"delete",confirmText:"Sí, salir y descartar cambios",cancelText:"Cancelar"});if(!confirmed)return;}dialog.value?.close()}function close(){dialog.value?.close()}function handleClosed(){attempted.value=false;keyboardId.value=null;dragId.value=null}function setError(value){errorMessage.value=String(value||"")}function clearError(){errorMessage.value=""}globalThis.addEventListener("keydown",handleKey,{capture:true});onBeforeUnmount(()=>globalThis.removeEventListener("keydown",handleKey,{capture:true}));defineExpose({openCreate,openEdit,close,setError,clearError});
</script>
